/* ==========================================================================
   Dorty na počkání — ORDER TICKET
   Jeden "lístek": velká levá část (nadpis, lead, 3 fakta jako řádky účtenky)
   + úzký útržek vpravo (razítko, kurýři, CTA), oddělené perforací.
   Fotka je přilepená páskou přes horní hranu lístku.

   POZOR: nahrazuje starý blok "Dorty na počkání" ve styles.css — po nasazení
   lze smazat pravidla .express-head, .express-lead, .steps-row, .step,
   .step-num, .step-ico, .express-strip, .express-photo, .express-cta,
   .express-badge, .couriers, .express-card, .express-macaron,
   .express-sprinkles včetně jejich media queries.
   ========================================================================== */
.express.express--ticket {
  position: relative;
  padding-block: clamp(3.2rem, 5.4vw, 4.4rem);
  overflow: clip;                 /* ozdoby nesmí tvořit vodorovný posuv */
}

/* ---------- Samotný lístek ---------- */
.tk {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(16.5rem, 24%, 20rem);
  background: #fff;
  border: var(--ol);
  border-radius: 26px;
  box-shadow: var(--shadow);
  transform: rotate(-.35deg);
}

/* ---------- Levá (hlavní) část lístku ---------- */
.tk-main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(11rem, 18vw, 14.5rem);
  grid-template-areas:
    "head snap"
    "facts facts";
  align-items: start;
  column-gap: clamp(1.2rem, 2.6vw, 2.2rem);
  padding: clamp(1.6rem, 2.8vw, 2.3rem) clamp(1.4rem, 2.6vw, 2.2rem) clamp(1.3rem, 2.2vw, 1.8rem);
  background-color: #fff;         /* .dots dodá jen halftone rastr */
  border-radius: 23px 0 0 23px;
}
.tk-head { grid-area: head; }
.tk-eyebrow { margin: 0 0 .5rem; color: var(--cherry); }
.tk-main h2 {
  font-size: clamp(1.85rem, 3.5vw, 2.85rem);
  margin-bottom: .3em;
}
.tk-lead {
  margin: 0;
  font-weight: 500;
  font-size: clamp(.95rem, 1.25vw, 1.03rem);
  max-width: 46ch;
}

/* ---------- Přilepená fotka přes horní hranu ---------- */
.tk-snap {
  grid-area: snap;
  position: relative;
  z-index: 4;
  margin: clamp(-5.6rem, -6vw, -4.2rem) 0 0;
  justify-self: end;
  width: 100%;
  padding: .5rem;
  background: #fff;
  border: var(--ol);
  border-radius: 14px;
  box-shadow: var(--shadow-sm);
  transform: rotate(2.4deg);
  transition: transform .35s var(--spring);
}
.tk-snap:hover { transform: rotate(0deg) scale(1.03); }
.tk-snap::before {                /* máslová lepicí páska */
  content: '';
  position: absolute;
  top: -8px;
  left: -13px;
  width: 84px;
  height: 26px;
  transform: rotate(-40deg);
  background: rgba(247, 201, 72, .85);
  border: 2px solid rgba(43, 21, 22, .35);
}
/* .anim-img je na vnitřním obalu, aby clip-path neořízl hard shadow rámečku */
.tk-snap-media {
  display: block;
  overflow: hidden;
  border-radius: 8px;
  border: 2px solid var(--ink);
  line-height: 0;
}
.tk-snap img {
  width: 100%;
  height: auto;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  object-position: 50% 44%;
}

/* ---------- Tři fakta jako řádky účtenky ---------- */
.tk-facts {
  grid-area: facts;
  list-style: none;
  margin: clamp(1.1rem, 2.2vw, 1.6rem) 0 0;
  padding: 0;
  border-top: 2px dashed rgba(43, 21, 22, .3);
}
.tk-fact {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr) auto;
  grid-template-areas:
    "ico title plate"
    "ico text  plate";
  align-items: center;
  column-gap: clamp(.8rem, 1.4vw, 1.1rem);
  padding-block: clamp(.7rem, 1.3vw, .95rem);
}
.tk-fact + .tk-fact { border-top: 2px dashed rgba(43, 21, 22, .3); }
.tk-fact-ico {
  grid-area: ico;
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  align-self: center;
  border: var(--ol);
  border-radius: 50%;
  box-shadow: 3px 3px 0 var(--ink);
  background: var(--pink-light);
  transform: rotate(-4deg);
}
.tk-fact-ico--pink { background: var(--pink-light); }
.tk-fact-ico--mint { background: var(--pistachio); transform: rotate(3deg); }
.tk-fact-ico--butter { background: var(--butter); transform: rotate(-2deg); }
.tk-fact-ico svg { display: block; }
.tk-fact h3 {
  grid-area: title;
  margin: 0;
  font-size: clamp(1.1rem, 1.55vw, 1.3rem);
}
.tk-fact p {
  grid-area: text;
  margin: .15rem 0 0;
  font-size: .87rem;
  line-height: 1.45;
  color: #5d4a45;
}
.tk-fact .plate {
  grid-area: plate;
  align-self: center;
  font-size: .95rem;
}
.tk-fact:nth-child(2) .plate { transform: rotate(1.8deg); }
.tk-fact:nth-child(3) .plate { transform: rotate(-2.6deg); }

/* ---------- Útržek (stub) ---------- */
.tk-stub {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: clamp(.9rem, 1.8vw, 1.35rem);
  padding: clamp(1.5rem, 2.4vw, 2rem) clamp(1.1rem, 1.8vw, 1.5rem);
  text-align: center;
  background: var(--pink-light);
  border-left: 3px dashed var(--ink);
  border-radius: 0 23px 23px 0;
}
/* perforační dírky na koncích trhací linky */
.tk-notch {
  position: absolute;
  left: -11.5px;
  width: 26px;
  height: 26px;
  background: var(--cream);
  border: var(--ol);
  border-radius: 50%;
  z-index: 3;
}
.tk-notch--a { top: -13px; }
.tk-notch--b { bottom: -13px; }

.tk-sticker {
  transform: rotate(-6deg);
  --r: -6deg;
  animation: bob 5.6s ease-in-out infinite;
}
.tk-delivery { min-width: 0; }
.tk-stub-label { margin: 0 0 .55rem; }
.tk-couriers {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .45rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.tk-courier { cursor: default; }
.tk-courier--mint { background: var(--pistachio); transform: rotate(-1.6deg); }
.tk-courier--pink { background: var(--pink); transform: rotate(1.4deg); }
.tk-courier--butter { background: var(--butter); transform: rotate(-1deg); }
.tk-cta {
  width: 100%;
  justify-content: center;
  text-align: center;
  font-size: clamp(.75rem, .95vw, .86rem);
  padding-inline: .9rem;
}

/* ---------- Ozdoby ukotvené do rohů lístku ---------- */
.tk-deco-sprinkles {
  width: 88px;
  height: 60px;
  top: -34px;
  left: -14px;
  transform: rotate(-16deg);
  z-index: 5;
}
.tk-deco-macaron {
  width: 76px;
  height: 59px;
  right: -18px;
  bottom: -26px;
  transform: rotate(12deg);
  z-index: 5;
}
.tk .deco { aspect-ratio: auto; }
.tk .deco svg { width: 100%; height: 100%; }

/* ---------- Responzivita ---------- */
@media (max-width: 1180px) {
  .tk-deco-sprinkles { left: -6px; top: -30px; }
  .tk-deco-macaron { right: -8px; }
}
@media (max-width: 900px) {
  .tk {
    grid-template-columns: minmax(0, 1fr);
    transform: rotate(0deg);
  }
  .tk-main {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "snap"
      "head"
      "facts";
    border-radius: 23px 23px 0 0;
    padding-top: 0;
  }
  .tk-head { margin-top: 1.2rem; }
  .tk-snap {
    width: min(250px, 46%);
    justify-self: start;
    margin: -2.2rem 0 0 clamp(1.4rem, 6vw, 3rem);
  }
  .tk-stub {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 1.1rem clamp(1.2rem, 3vw, 2rem);
    border-left: 0;
    border-top: 3px dashed var(--ink);
    border-radius: 0 0 23px 23px;
    padding-block: 1.6rem;
  }
  .tk-notch {
    top: -13px;
    bottom: auto;
    left: -13px;
  }
  .tk-notch--b { left: auto; right: -13px; }
  .tk-couriers { flex-direction: row; flex-wrap: wrap; justify-content: center; }
  .tk-cta { width: auto; }
  .tk-deco-sprinkles { display: none; }
  .tk-deco-macaron { width: 58px; height: 45px; right: -6px; bottom: -18px; }
}
@media (max-width: 560px) {
  .tk-fact {
    grid-template-columns: 44px minmax(0, 1fr);
    grid-template-areas:
      "ico title"
      "ico text"
      "ico plate";
    column-gap: .8rem;
  }
  .tk-fact-ico { width: 44px; height: 44px; align-self: start; margin-top: .1rem; }
  .tk-fact .plate { justify-self: start; margin-top: .55rem; }
  .tk-snap { width: min(215px, 62%); }
  .tk-stub { flex-direction: column; }
  .tk-cta { width: 100%; max-width: 20rem; }
}

/* ==========================================================================
   Dorty na počkání — „účtenka“ (horizontální timeline + cinematic banner)
   Nahrazuje původní blok .express-head / .steps-row / .step / .express-strip
   ========================================================================== */
.express {
  position: relative;
  padding-block: clamp(3rem, 6vw, 4.5rem);
}

/* ---------- 1. Kompaktní hlavička ---------- */
.xp-head {
  max-width: 940px;
  margin: 0 auto clamp(1.4rem, 2.4vw, 1.8rem);
  text-align: center;
}
.xp-kicker { margin: 0 0 .85rem; }
.xp-kicker .chip { padding: .45rem 1.05rem; }
.xp-head h2 {
  font-size: clamp(1.8rem, 3.7vw, 2.65rem);
  margin-bottom: .32em;
}
.xp-lead {
  max-width: 640px;
  margin: 0 auto;
  font-weight: 500;
  text-wrap: balance;
}

/* ---------- 2. Účtenka: tři kroky na jedné lince ---------- */
.xp-strip {
  --node: 56px;
  --g: 1.6rem;
  position: relative;
  background: #fff;
  border: var(--ol);
  border-radius: 26px;
  box-shadow: var(--shadow);
  padding: 1.7rem clamp(1.1rem, 2.6vw, 2.2rem) 1.5rem;
  margin-bottom: clamp(2rem, 2.8vw, 2.3rem);
  transform: rotate(-.45deg);
}
/* třešeň nalepená na rohu účtenky */
.xp-sticker {
  position: absolute;
  z-index: 3;
  top: -20px;
  left: -14px;
  width: 56px;
  height: 56px;
  line-height: 0;
  pointer-events: none;
  transform: rotate(-14deg);
}
.xp-sticker svg { width: 100%; height: 100%; display: block; }

.xp-steps {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--g);
  margin: 0;
  padding: 0;
  list-style: none;
}
/* přerušovaná linka přesně mezi středy prvního a posledního kolečka */
.xp-steps::before {
  content: '';
  position: absolute;
  z-index: 0;
  top: calc(var(--node) / 2);
  left: calc((100% - 2 * var(--g)) / 6);
  right: calc((100% - 2 * var(--g)) / 6);
  border-top: 3px dashed var(--ink);
}
.xp-step {
  position: relative;
  margin: 0;
  text-align: center;
}
/* šipka přesně v půli mezery mezi kroky */
.xp-step + .xp-step::before {
  content: '';
  position: absolute;
  z-index: 1;
  top: calc(var(--node) / 2);
  left: calc(var(--g) / -2);
  width: 11px;
  height: 11px;
  border-top: 3px solid var(--ink);
  border-right: 3px solid var(--ink);
  transform: translate(-50%, -50%) rotate(45deg);
}

.xp-node {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: var(--node);
  height: var(--node);
  margin: 0 auto .6rem;
  border: var(--ol);
  border-radius: 50%;
  background: var(--pink-light);
  box-shadow: var(--shadow-sm);
}
.xp-step:nth-child(2) .xp-node { background: var(--pistachio); }
.xp-step:nth-child(3) .xp-node { background: var(--butter); }
.xp-ico { width: 33px; height: 33px; display: block; }
.xp-ico--cupcake { width: 30px; height: 36px; }

.xp-num {
  position: absolute;
  top: -12px;
  left: -13px;
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  border: var(--ol);
  border-radius: 50%;
  background: var(--cherry);
  color: var(--cream);
  font-family: var(--agbalumo);
  font-size: .76rem;
  line-height: 1;
  transform: rotate(-8deg);
}

.xp-step h3 {
  font-size: clamp(1.1rem, 1.7vw, 1.38rem);
  margin: 0 0 .3em;
}
.xp-step p {
  margin: 0;
  font-size: .85rem;
  line-height: 1.5;
  color: #5D4A45;
  text-wrap: pretty;
}

/* ---------- 3. Široký banner + odtrhávací lišta ---------- */
.xp-banner {
  position: relative;
  background: #fff;
  border: var(--ol);
  border-radius: 24px;
  box-shadow: var(--shadow);
  transform: rotate(.35deg);
}
.xp-photo {
  margin: 0;
  overflow: hidden;
  border-radius: 21px 21px 0 0;
}
.xp-photo img {
  display: block;
  width: 100%;
  height: clamp(160px, 15vw, 205px);
  object-fit: cover;
  object-position: 50% 40%;
}
.xp-badge {
  position: absolute;
  z-index: 2;
  top: -20px;
  right: 24px;
  width: 104px;
  height: 104px;
  font-size: .7rem;
  --r: 9deg;
  transform: rotate(9deg);
  animation: bob 5.4s ease-in-out infinite;
}

.xp-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .8rem 1.4rem;
  padding: .72rem 1rem .72rem 1.3rem;
  background: #fff;
  border-top: 3px dashed var(--ink);
  border-radius: 0 0 21px 21px;
}
.xp-couriers {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: .5rem .55rem;
  margin: 0;
}
.xp-couriers-label {
  font-weight: 700;
  font-size: .74rem;
  text-transform: uppercase;
  letter-spacing: .13em;
}
.xp-bar .chip { box-shadow: 3px 3px 0 var(--ink); }
.xp-cta { padding: .8rem 1.45rem; }

/* ---------- Responsivita ---------- */
@media (max-width: 1080px) {
  .xp-strip { --g: 1.2rem; }
}
@media (max-width: 900px) {
  .xp-head { margin-bottom: 1.5rem; }
  .xp-strip {
    --g: 1.5rem;
    padding: 1.5rem 1.2rem 1.3rem;
    margin-bottom: 2.2rem;
    transform: rotate(-.3deg);
  }
  .xp-sticker { width: 46px; height: 46px; top: -16px; left: -8px; }
  .xp-steps { grid-template-columns: 1fr; }
  .xp-steps::before { display: none; }

  /* kolečko vlevo, text vpravo */
  .xp-step {
    display: grid;
    grid-template-columns: var(--node) 1fr;
    column-gap: 1.05rem;
    text-align: left;
  }
  .xp-node { grid-column: 1; grid-row: 1 / span 2; margin: 0; }
  .xp-step h3 { grid-column: 2; grid-row: 1; }
  .xp-step p  { grid-column: 2; grid-row: 2; }

  /* linka se překlopí do svislé */
  .xp-step:not(:last-child)::after {
    content: '';
    position: absolute;
    top: calc(var(--node) + 9px);
    bottom: calc(var(--g) * -1 + 9px);
    left: calc(var(--node) / 2);
    border-left: 3px dashed var(--ink);
    transform: translateX(-1.5px);
  }
  .xp-step + .xp-step::before {
    top: calc(var(--g) / -2);
    left: calc(var(--node) / 2);
    transform: translate(-50%, -50%) rotate(135deg);
  }

  .xp-banner { transform: rotate(.25deg); }
  .xp-badge { width: 84px; height: 84px; font-size: .62rem; top: -17px; right: 8px; }
  .xp-bar {
    flex-direction: column;
    align-items: stretch;
    gap: .8rem;
    padding: .85rem 1rem;
  }
  .xp-couriers { justify-content: center; }
  .xp-cta { justify-content: center; }
}
@media (max-width: 420px) {
  .xp-couriers-label { width: 100%; text-align: center; }
}

/* ==========================================================================
   Dorty na počkání — ASYMMETRIC SPLIT (jeden panel, levý sloupec = obsah,
   pravý sloupec = fotka v pastelovém bloku)
   Nahrazuje původní sekci "Dorty na počkání" (.express-head, .steps-row,
   .step, .express-strip, .express-photo, .express-cta, .express-badge,
   .couriers, .express-macaron, .express-sprinkles).
   ========================================================================== */
.express {
  position: relative;
  padding-block: clamp(3rem, 6vw, 4.5rem);
}

/* ---------- Panel ---------- */
.xp-panel {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr);
  align-items: stretch;
  background: var(--cream);
  border: var(--ol);
  border-radius: 26px;
  box-shadow: var(--shadow);
}

/* ---------- Levý sloupec: text ---------- */
.xp-copy {
  min-width: 0;
  padding: clamp(1.6rem, 2.9vw, 2.5rem) clamp(1.5rem, 2.6vw, 2.2rem)
           clamp(1.7rem, 2.9vw, 2.5rem) clamp(1.6rem, 3vw, 2.6rem);
}
.xp-eyebrow { margin: 0 0 .45rem; }
.xp-title {
  font-size: clamp(1.85rem, 3.2vw, 2.65rem);
  margin: 0 0 .38em;
}
.xp-lead {
  margin: 0;
  font-weight: 500;
  font-size: clamp(.95rem, 1.2vw, 1.02rem);
  line-height: 1.55;
  max-width: 46ch;
}

/* ---------- Tři fakta jako kompaktní číslovaný seznam ---------- */
.xp-steps {
  list-style: none;
  margin: 1.35rem 0 0;
  padding: 0;
}
.xp-step {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  column-gap: .95rem;
  align-items: start;
}
.xp-step + .xp-step {
  margin-top: .85rem;
  padding-top: .85rem;
  border-top: 2px dashed rgba(43, 21, 22, .22);
}
.xp-num {
  grid-column: 1;
  grid-row: 1 / span 2;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  margin-top: 2px;
  border: var(--ol);
  border-radius: 50%;
  box-shadow: 3px 3px 0 var(--ink);
  font-family: var(--agbalumo);
  font-size: 1.25rem;
  line-height: 1;
}
.xp-num--1 { background: var(--cherry); color: var(--cream); transform: rotate(-7deg); }
.xp-num--2 { background: var(--pistachio); color: var(--ink); transform: rotate(6deg); }
.xp-num--3 { background: var(--butter); color: var(--ink); transform: rotate(-5deg); }
.xp-step-title {
  grid-column: 2;
  grid-row: 1;
  font-size: clamp(1.02rem, 1.5vw, 1.18rem);
  margin: 0 0 .18em;
}
.xp-step-text {
  grid-column: 2;
  grid-row: 2;
  margin: 0;
  font-size: .89rem;
  line-height: 1.5;
  color: #5d4a45;
}

/* ---------- Akce: jeden hlavní CTA + kurýři pod ním ---------- */
.xp-action {
  display: grid;
  justify-items: start;
  gap: .85rem;
  margin-top: 1.5rem;
}
.xp-couriers {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .45rem;
  margin: 0;
}
.xp-couriers-label {
  font-weight: 700;
  font-size: .7rem;
  text-transform: uppercase;
  letter-spacing: .16em;
  margin-right: .2rem;
}
.xp-couriers .chip { font-size: .74rem; padding: .42rem .85rem; }

/* ---------- Pravý sloupec: pastelový blok s fotkou ---------- */
.xp-media {
  position: relative;
  margin: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: .9rem;
  padding: clamp(1.5rem, 2.6vw, 2rem) clamp(1.4rem, 2.4vw, 1.9rem)
           clamp(4.25rem, 6vw, 5.5rem);
  background-color: var(--pink-light);
  border-left: var(--ol);
  border-radius: 0 23px 23px 0;
}
.xp-figure {
  position: relative;
  width: 100%;
  transform: rotate(-1.6deg);
}
.xp-photo {
  border: var(--ol);
  border-radius: 18px;
  overflow: hidden;
  box-shadow: var(--shadow);
  background: var(--cream);
  line-height: 0;
}
.xp-photo img {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  object-position: 50% 42%;
}
.badge-circle.xp-sticker {
  position: absolute;
  top: -30px;
  right: -20px;
  z-index: 3;
  width: 104px;
  height: 104px;
  padding: .6rem;
  font-size: .7rem;
  --r: 8deg;
  transform: rotate(8deg);
  animation: bob 5.6s ease-in-out infinite;
}
.xp-cap {
  max-width: 92%;
  margin: 0;
  padding: .48rem .9rem;
  background: var(--cream);
  border: var(--ol);
  border-radius: 14px;
  box-shadow: var(--shadow-sm);
  text-align: center;
  font-weight: 700;
  font-size: .76rem;
  line-height: 1.35;
  text-transform: uppercase;
  letter-spacing: .05em;
  transform: rotate(1.4deg);
}

/* ---------- Dekorace ukotvené k hranám panelu ---------- */
.xp-deco { z-index: 4; }
.xp-deco--sprinkles {
  width: 82px;
  height: 56px;
  aspect-ratio: auto;
  top: -24px;
  left: -10px;
  transform: rotate(-14deg);
}
/* cukrarsky stojan stoji na spodni hrane pastelového bloku */
.xp-deco--stand {
  width: clamp(150px, 34%, 200px);
  height: auto;
  aspect-ratio: 200 / 90;
  left: 50%;
  bottom: -14px;
  transform: translateX(-50%) rotate(-1.5deg);
}
.xp-deco--macaron {
  width: 66px;
  height: 52px;
  aspect-ratio: auto;
  right: 10px;
  bottom: 14px;
  transform: rotate(12deg);
}

/* ---------- Responsivita ---------- */
@media (max-width: 1080px) {
  .xp-panel { grid-template-columns: minmax(0, 1.12fr) minmax(0, .88fr); }
  .xp-step { grid-template-columns: 40px minmax(0, 1fr); column-gap: .8rem; }
  .xp-num { width: 40px; height: 40px; font-size: 1.12rem; }
  .badge-circle.xp-sticker { width: 92px; height: 92px; font-size: .64rem; top: -24px; right: -16px; }
}

@media (max-width: 900px) {
  .xp-panel { grid-template-columns: minmax(0, 1fr); }
  .xp-media {
    border-left: 0;
    border-top: var(--ol);
    border-radius: 0 0 23px 23px;
    padding: clamp(1.6rem, 5vw, 2.1rem) clamp(1.4rem, 4vw, 1.9rem)
             clamp(4.5rem, 9vw, 5.25rem);
  }
  .xp-figure { max-width: 520px; }
  .xp-photo img { aspect-ratio: 16 / 10; }
  .xp-lead { max-width: none; }
  .xp-deco--sprinkles { left: -6px; }
  .xp-deco--stand { width: 168px; }
}

@media (max-width: 560px) {
  .xp-copy { padding: 1.5rem 1.25rem 1.7rem; }
  .xp-step { grid-template-columns: 36px minmax(0, 1fr); column-gap: .7rem; }
  .xp-num { width: 36px; height: 36px; font-size: 1rem; box-shadow: 2px 2px 0 var(--ink); }
  .xp-step-text { font-size: .86rem; }
  .xp-action { justify-items: stretch; }
  .xp-action .btn { width: 100%; justify-content: center; }
  .xp-couriers { gap: .4rem; }
  .xp-couriers-label { flex: 1 0 100%; margin: 0 0 .15rem; }
  .badge-circle.xp-sticker { width: 78px; height: 78px; font-size: .56rem; top: -20px; right: -10px; padding: .45rem; }
  .xp-cap { max-width: 100%; font-size: .72rem; }
  .xp-deco--sprinkles { width: 62px; height: 42px; top: -18px; }
  .xp-deco--stand { width: 132px; }
  .xp-deco--macaron { width: 52px; height: 41px; right: 10px; bottom: 18px; }
}

/* ==========================================================================
   Dorty na počkání — photo-led hero panel
   Fotka je pozadím celého panelu, krémová "cedulka" leží přes ni,
   kurýři sedí v tenkém inkoustovém pruhu podél spodní hrany fotky.
   Nahrazuje původní blok .express* (styles.css ř. 893–1005
   + .express-macaron/.express-sprinkles v sekci SVG dekorace) — ten lze smazat.
   ========================================================================== */
.pohotovost {
  position: relative;
  padding-block: clamp(2.6rem, 5vw, 4.2rem);
}

.poh-panel {
  --strip-h: 3.1rem;              /* výška kurýrního pruhu */
  --card-w: min(548px, 53%);      /* šířka cedulky */
  --card-inset: 1.5rem;           /* odsazení cedulky od hran panelu */
  position: relative;
  min-height: clamp(280px, 30vw, 420px);
  padding-top: var(--card-inset);
  padding-bottom: calc(var(--strip-h) + 1.1rem);
}

/* ---------- Fotka = pozadí celého panelu ---------- */
.poh-photo {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  flex-direction: column;
  margin: 0;
  background: var(--pink-light);
  border: var(--ol);
  border-radius: 26px;
  box-shadow: var(--shadow);
  overflow: hidden;
}
.poh-photo img {
  flex: 1 1 0;
  min-height: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 92% 50%;   /* cukrářka s dortem do odkryté levé části */
}

/* ---------- Kurýrní pruh podél spodní hrany fotky ---------- */
.poh-strip {
  flex: none;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .45rem;
  min-height: var(--strip-h);
  padding: .4rem .9rem;
  background: var(--ink);
  border-top: var(--ol);
  color: var(--cream);
}
.poh-strip-label {
  color: var(--butter);
  font-weight: 700;
  font-size: .68rem;
  text-transform: uppercase;
  letter-spacing: .16em;
  white-space: nowrap;
  margin-right: .2rem;
}
.poh-strip .chip {
  padding: .28rem .8rem;
  font-size: .72rem;
  color: var(--ink);          /* pruh dědí krémovou, chip musí zpět na inkoust */
  box-shadow: none;
}

/* ---------- Krémová cedulka přes fotku ---------- */
.poh-card {
  position: relative;
  z-index: 3;
  width: var(--card-w);
  margin-left: auto;
  margin-right: var(--card-inset);
  padding: clamp(1.15rem, 1.8vw, 1.5rem) clamp(1.15rem, 1.8vw, 1.5rem) clamp(1.25rem, 2vw, 1.6rem);
  background: var(--cream);
  border: var(--ol);
  border-radius: 22px;
  box-shadow: var(--shadow);
  transform: rotate(-.6deg);
}
.poh-eyebrow { margin: 0 0 .45rem; }
.poh-title {
  font-size: clamp(1.7rem, 3.05vw, 2.5rem);
  margin: 0 0 .3em;
}
.poh-lead {
  font-weight: 500;
  font-size: clamp(.92rem, 1.05vw, 1rem);
  line-height: 1.5;
  margin: 0 0 clamp(.9rem, 1.5vw, 1.15rem);
}

/* ---------- Tři fakta jako řádkové pilulky ---------- */
.poh-facts {
  list-style: none;
  display: grid;
  gap: .45rem;
  margin: 0 0 clamp(1rem, 1.7vw, 1.3rem);
  padding: 0;
}
.poh-fact {
  display: flex;
  align-items: center;
  gap: .6rem;
  padding: .35rem .85rem .35rem .4rem;
  background: var(--pink-light);
  border: var(--ol);
  border-radius: 16px;
}
.poh-fact:nth-child(2) { background: #DDF0E7; }
.poh-fact:nth-child(3) { background: #FDEFC4; }
.poh-fact-ico {
  flex: none;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  background: var(--cream);
  border: 2px solid var(--ink);
  border-radius: 50%;
  line-height: 0;
}
.poh-fact-ico svg { display: block; }
.poh-fact-body {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: .4rem;
  min-width: 0;
}
.poh-fact-label {
  font-size: .95rem;
  line-height: 1.1;
  margin: 0;
}
.poh-fact-note {
  font-size: .8rem;
  line-height: 1.3;
  color: #5d4a45;
  margin: 0;
}

.poh-cta { margin: 0; }

/* ---------- Nálepka ukotvená do rohu cedulky ---------- */
.poh-sticker {
  --s: 92px;
  position: absolute;
  z-index: 4;
  top: -2.6rem;
  left: calc(22px - var(--s));     /* do cedulky zasahuje jen 22 px = roh */
  width: var(--s);
  height: var(--s);
  padding: .5rem;
  font-size: .66rem;
  --r: -9deg;
  transform: rotate(var(--r));
  animation: bob 5.4s ease-in-out infinite;
}

/* ---------- Dekorace ukotvené do rohů panelu ---------- */
.poh-deco-sprinkles {
  z-index: 4;
  width: 86px;
  aspect-ratio: 100 / 68;
  top: -1.4rem;
  left: -.9rem;
  transform: rotate(-14deg);
}
.poh-deco-macaron {
  z-index: 4;
  width: 74px;
  aspect-ratio: 100 / 78;
  right: -1rem;
  bottom: -1.2rem;
  transform: rotate(12deg);
}

/* ---------- Responzivita ---------- */
@media (max-width: 1040px) {
  .poh-panel { --card-w: min(460px, 52%); --card-inset: 1.1rem; }
  .poh-photo img { object-position: 74% 50%; }   /* užší výřez → dort zpět do záběru */
  .poh-strip { padding-inline: .7rem; gap: .35rem; }
  .poh-strip-label { font-size: .62rem; letter-spacing: .12em; }
  .poh-strip .chip { padding: .24rem .65rem; font-size: .66rem; }
  .poh-sticker { --s: 80px; font-size: .58rem; top: -2.1rem; }
}

@media (max-width: 900px) {
  .poh-panel {
    --card-w: 100%;
    --card-inset: 0rem;
    min-height: 0;
    padding: 0;
  }
  .poh-photo {
    position: relative;
    inset: auto;
  }
  .poh-photo img {
    flex: none;
    height: auto;
    aspect-ratio: 16 / 7;
    object-position: 66% 50%;
  }
  .poh-strip { justify-content: center; padding-inline: 1rem; }
  .poh-card {
    width: auto;
    margin: 1.2rem 0 0;
    transform: rotate(-.5deg);
  }
  .poh-sticker { --s: 76px; top: -1.3rem; left: auto; right: -.6rem; --r: 8deg; }
  .poh-deco-sprinkles { display: none; }
  .poh-deco-macaron { width: 58px; right: .4rem; bottom: -1.3rem; }
}

@media (max-width: 480px) {
  .poh-photo img { aspect-ratio: 3 / 2; object-position: 59% 50%; }
  .poh-strip { padding-inline: .65rem; gap: .3rem; }
  .poh-strip-label { font-size: .58rem; letter-spacing: .1em; }
  .poh-strip .chip { padding: .22rem .55rem; font-size: .62rem; }
  .poh-fact { align-items: flex-start; padding-block: .45rem; }
  .poh-fact-ico { margin-top: .1rem; }
  .poh-sticker { --s: 68px; font-size: .55rem; top: -1.1rem; }
  .poh-deco-macaron { display: none; }
  .poh-cta .btn { width: 100%; justify-content: center; }
}
